def doc(route,title,desc,h1,body):
 u='https://saleson.co.in'+route;schema={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':u,'dateModified':'2026-10-28'}
 return '<!doctype html>\n<html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+E(title)+' | SalesOn</title><meta name="description" content="'+E(desc)+'"><link rel="canonical" href="'+u+'"><meta property="og:url" content="'+u+'"><meta property="og:title" content="'+E(title)+'"><meta property="og:description" content="'+E(desc)+'"><link rel="stylesheet" href="/css/site-repairs.css"><link rel="stylesheet" href="/css/workflow-guides.css"><script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script><script defer src="/assets/js/page-readiness.js"></script></head><body class="repair-page workflow-page">'+HEADER+'<main id="main-content"><header><h1>'+E(h1)+'</h1><p class="repair-lead">'+E(desc)+'</p><div class="repair-actions"><a href="/request-demo">Walk through your workflow</a><a href="/pricing">See pricing</a></div><p class="workflow-commercial">₹0 setup · Minimum 2 users · Monthly or annual billing · Internet required</p></header>'+body+'</main>'+FOOTER+'</body></html>\n'
for slug,title,heading,lead,steps,exhead,example,questions,modules,faq in DATA:
 body='<section id="industry-workflow"><p class="workflow-eyebrow">'+E(heading)+'</p><h2>A daily workflow for '+{'fmcg':'FMCG distribution'}.get(slug,title.replace(' software','').lower())+'</h2><div class="workflow-guide-grid">'
 for i,(head,text) in enumerate(steps,1):body+='<article><span class="workflow-step">'+str(i)+'</span><h3>'+E(head)+'</h3><p>'+E(text)+'</p></article>'
 body+='</div></section><section><h2>'+E(exhead)+'</h2><p>'+E(example)+'</p></section><section><h2>Bring these questions to your demo</h2><ul>'+''.join('<li>'+E(q)+'</li>' for q in questions)+'</ul></section><section><h2>'+E(faq[0])+'</h2><p>'+E(faq[1])+'</p></section><nav class="workflow-related" aria-label="Related product workflows">'+ ' · '.join('<a href="'+url+'">'+E(label)+'</a>' for url,label in modules)+'</nav>'
 (W/'industries'/(slug+'.html')).write_text(doc('/industries/'+slug,title,lead,title,body))
# Primary commercial manufacturer page: buyer fit and rollout. No procurement marketplace promises.
body='''<section><h2>Connect the factory’s output with the sales team’s demand</h2><div class="workflow-guide-grid"><article><h3>Sales and distributor accounts</h3><p>Review distributor/customer records, recorded orders, customer prices and outstanding balances. Give the field team the outlet context needed for its sales work.</p></article><article><h3>Finished goods and fulfilment</h3><p>Review availability by godown and follow the order into invoicing and delivery. Keep sales, dispatch and accounts involved in the same operating review.</p></article><article><h3>Production when it is in scope</h3><p>The Production module covers BOMs, work orders, recorded material use, costs and finished output. Review it separately if your team needs factory operations as well as sales.</p></article></div></section><section><h2>Choose the part of the business you need to improve</h2><p>A manufacturer with an established factory system may need field orders and distributor collections first. Another may need to review production costing alongside finished stock. Use your own brief to select modules rather than assuming every workflow needs replacing.</p><ul><li>Sales owner: customer access, prices, demand and territory review.</li><li>Dispatch team: available stock and the delivery handover.</li><li>Accounts team: invoices, outstanding balances and the required Tally records.</li><li>Production team: BOMs and work-order/costing requirements, where relevant.</li></ul></section><section><h2>Prepare a manufacturer-specific demonstration</h2><p>Bring one distributor order, a finished-goods stock example and the related invoice. Add a BOM and batch-cost sheet only if production is part of the brief. Ask who creates, reviews and changes each record.</p><p>Confirm godown structure, users and permissions, connectivity, accounting versions and data migration before agreeing rollout timing. SalesOn requires internet and does not support offline use.</p></section><section><h2>Start small and confirm the full scope</h2><p>SalesOn has a ₹0 setup fee and a minimum of 2 users. Choose monthly or annual billing on the <a href="/pricing">current pricing page</a>; GST is extra as applicable. Van Sales is Enterprise functionality. Discuss onboarding, training and support arrangements using the workflows you plan to run.</p></section><section><h2>Is this a replacement for every manufacturing ERP?</h2><p>No. The published modules establish specific production and sales workflows, not universal ERP parity. Demonstrate specialist procurement, planning, quality, compliance or integration requirements before committing.</p></section><nav class="workflow-related" aria-label="Manufacturer workflows"><a href="/industries/manufacturing">Example: distributor order to dispatch</a> · <a href="/production">Production module</a> · <a href="/distribution-management-system">DMS</a> · <a href="/tally-integration">Tally handover</a></nav>'''
(W/'user/software-for-manufacturers.html').write_text(doc('/user/software-for-manufacturers','Sales and distribution software for manufacturers','For manufacturers choosing how to connect distributor orders, finished-goods stock, billing and collections—with Production available for factory work orders and costing.','Sales and distribution software for manufacturers',body))
body='''<section><h2>Review product availability by godown</h2><p>SalesOn DMS supports stock visibility across multiple godowns. Compare where goods are available before the office allocates supply or prepares fulfilment. Review the item, quantity and location your staff needs rather than treating a single total as sufficient.</p><p>For products managed with batch and expiry records, SalesOn lets the team review that information alongside stock. Confirm the controls needed for your categories during the demo.</p></section><section><h2>Follow stock in its sales context</h2><div class="workflow-guide-grid"><article><h3>Review the order</h3><p>Check the requested product and quantity against the stock information available to the office.</p></article><article><h3>Prepare fulfilment</h3><p>Review the godown, invoice and delivery handover with the team responsible for supply.</p></article><article><h3>Review an exception</h3><p>Bring a return or stock discrepancy to the demo and establish the record, permissions and accounting treatment required.</p></article></div></section><section><h2>Keep warehouse stock and van stock distinct</h2><p>Van Sales has its own load, sale, return and closing-stock review. It is included in Enterprise. If goods move from a godown to vehicles, ask the team to show your actual movement and reconciliation process rather than assuming a loading sheet alone updates inventory.</p></section><section><h2>Use free planning tools for a separate task</h2><p>The <a href="/tools/stock-reorder-level-calculator">free reorder calculator</a> helps plan quantities; the <a href="/tools/purchase-order-generator">purchase order tool</a> prepares a document. They do not automatically create a cloud inventory receipt or purchase bill. Product inventory is the operational workflow evaluated in SalesOn.</p></section><section><h2>What should we check before rollout?</h2><ul><li>Product list, selling units, opening stock and godown structure.</li><li>Whether batch, expiry, serial-number or specialist controls are needed; confirm the exact supported scope.</li><li>The user who can change stock records and how exceptions are reviewed.</li><li>Your accounting transaction types and Tally configuration.</li></ul><p>This page establishes multi-godown visibility and configured batch/expiry review from the published DMS workflow. It does not promise a full warehouse-management, barcode-scanning or demand-forecasting system. SalesOn needs internet.</p></section><nav class="workflow-related" aria-label="Related inventory workflows"><a href="/distribution-management-system">DMS stock and accounts</a> · <a href="/van-sales">Van stock reconciliation</a> · <a href="/production">Finished production</a> · <a href="/pricing">Plans and inclusions</a></nav>'''
(W/'inventory-management.html').write_text(doc('/inventory-management','Inventory management software for distributors','Review product stock by godown, configured batch and expiry records, and the stock context behind ordering, billing and van operations.','Inventory management for distributors',body))
body='''<section><h2>Review the sale before preparing the bill</h2><p>Keep the customer details, selected items, quantities and prices together while reviewing the order. Use the catalogue and order workflow to establish what the customer wants; use Invoicing to prepare the billing document.</p><p>A repeat-customer example is useful: find the correct product, review the price, confirm quantity and prepare the invoice with your billing user.</p></section><section><h2>Share or print the invoice</h2><p>SalesOn’s published invoicing workflow supports PDF sharing and A4/A5 or supported thermal formats. Your team chooses the correct GST setup and transaction treatment. For thermal printing, check the printer model, paper width, phone and connection before rollout.</p><p>A PDF invoice and a registered e-invoice are different. If registration is required for your business, ask for the relevant supported setup and response to be demonstrated.</p></section><section><h2>Review customer dues and stock with the office</h2><div class="workflow-guide-grid"><article><h3>Customer balance</h3><p>Follow recorded collections and remaining dues through the customer account.</p></article><article><h3>Product availability</h3><p>Review the stock information relevant to the sale. For more than one godown, check the DMS workflow.</p></article><article><h3>Credit adjustment</h3><p>Use an actual return/credit-note example with accounts. A credit adjustment and a cash refund are different actions.</p></article></div></section><section><h2>Check your counter requirements before choosing</h2><p>This page brings together supported order, invoicing, stock-review and collection functions. It does not establish a dedicated retail POS, consumer ecommerce checkout or payment-gateway integration.</p><ul><li>Bring your usual invoice and printer details.</li><li>Test your product identification, units and any barcode requirement separately.</li><li>Confirm cash-counter, return and payment processes with the team.</li><li>Test internet availability; SalesOn does not support offline use.</li></ul></section><section><h2>Is this the free invoice generator?</h2><p>No. The <a href="/tools/gst-invoice-generator">free GST invoice generator</a> creates an individual document in your browser. A SalesOn account provides the product workflow your business team evaluates. Plans start with a minimum of 2 users and ₹0 setup; <a href="/pricing">review current INR pricing</a> and module inclusions.</p></section><nav class="workflow-related" aria-label="Retailer product workflows"><a href="/invoicing">Invoice formats</a> · <a href="/payment-collection">Customer collections</a> · <a href="/inventory-management">Stock review</a></nav>'''
(W/'user/software-for-retailers.html').write_text(doc('/user/software-for-retailers','Orders and billing software for retailers','Evaluate customer orders, invoice sharing and printing, stock review and payment records for your retail business. Confirm counter/POS requirements in a demo.','Orders, billing and customer dues for retailers',body))
print('Built 12 industry pages, primary manufacturer page, Inventory and Retailer pages.')
